const PROFILE_BLOCKED_PATTERNS=[
  /\b(fdp|vtnc|vsf)\b/i,
  /\b(filho\s*da\s*puta|filha\s*da\s*puta|vai\s*tomar\s*no\s*cu|tomar\s*no\s*cu)\b/i,
  /\b(porra|caralho|buceta|arrombado|arrombada|merda)\b/i,
  /\b(retardado|retardada|mongoloide)\b/i,
  /\b(viado|viadinho|bicha)\b/i,
  /\b(macaco|macaca)\b/i,
  /\b(nazi|nazista|nazismo|neonazi|neo\s*nazi|hitler|sieg\s*heil|heil\s*hitler|svastica|suastica|swastika)\b/i,
  /\b(white\s*power|supremacia\s*branca|supremacista\s*branco|1488)\b/i
];
function normalizeProfileText(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[@4]/g,'a').replace(/[3]/g,'e').replace(/[1!]/g,'i').replace(/[0]/g,'o').replace(/[$5]/g,'s').replace(/[7]/g,'t').replace(/[_\-.]+/g,' ').replace(/\s+/g,' ').trim();}
function profileModerationReason(value,label='texto'){const raw=String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),normalized=normalizeProfileText(value);if(!normalized)return '';if(/[卐卍]/.test(String(value||''))||/\b1488\b/.test(raw)||PROFILE_BLOCKED_PATTERNS.some(rx=>rx.test(normalized)))return `O ${label} contém conteúdo que não é permitido no perfil.`;if(/(.)\1{10,}/i.test(normalized))return `O ${label} parece conter spam ou repetição excessiva.`;return '';}

const publicRequests=new Map(),PUBLIC_CACHE_MS=5*60*1000;
function publicCacheKey(path){const u=new URL(path,API);if(u.pathname==='/api/ranking'&&!u.searchParams.has('week')&&!u.searchParams.has('month'))return 'cff-community-ranking-cache-v2:'+(u.searchParams.get('period')||'week');return 'cff-community-public-cache-v1:'+path;}
async function api(path,force=false){
 const shared=/^\/api\/(ranking(?:[/?]|$)|achievements\/profile[?]|prediction\/ranking[?]|community\/(?:profile|peers)[?])/.test(path),key=shared?publicCacheKey(path):'';
 if(shared&&!force){try{const saved=JSON.parse(readLocal(key)||'null');if(saved?.raw&&Date.now()-saved.savedAt<PUBLIC_CACHE_MS)return saved.raw;}catch{}}
 if(shared&&publicRequests.has(key))return publicRequests.get(key);
 const job=(async()=>{const r=await fetch(API+path,{cache:shared&&!force?'default':'no-store'}),d=await r.json();if(!r.ok)throw Error(d.error||'Falha ao consultar Instagram');if(shared)writeLocal(key,JSON.stringify({savedAt:Date.now(),raw:d}));return d;})();
 if(shared)publicRequests.set(key,job);try{return await job;}finally{if(shared)publicRequests.delete(key);}
}
function accountRef(path='',uid=user?.uid){if(!uid)throw Error('Entre com Google primeiro.');return ref(database,'userAccounts/'+uid+(path?'/'+path:''));}
async function slugDigits(uid){const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(String(uid||''))),hex=[...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join(''),digits=BigInt('0x'+hex).toString(10);return (digits+'0000000000').slice(0,10);}
async function ensureProfileSlug(uid){if(!uid)return '';const reverse=ref(database,'communityProfileSlugByUid/'+uid),current=(await get(reverse)).val();if(/^user\d{6,10}$/.test(String(current||'')))return current;const digits=await slugDigits(uid);for(let len=6;len<=10;len++){const slug='user'+digits.slice(0,len),claim=ref(database,'communityProfileSlugs/'+slug),result=await runTransaction(claim,value=>!value||value===uid?uid:undefined);if(result.committed&&result.snapshot.val()===uid){await set(reverse,slug);return slug;}}return '';}
async function profileSlugForUid(uid){try{const value=(await get(ref(database,'communityProfileSlugByUid/'+uid))).val();return /^user\d{6,10}$/.test(String(value||''))?String(value):'';}catch{return '';}}
function profilePath(username='',slug=''){const ig=String(username||'').replace(/^@+/,'').toLowerCase();if(/^[a-z0-9_.]{1,64}$/.test(ig))return '/perfil/@'+ig;if(/^user\d{6,10}$/.test(String(slug||'')))return '/perfil/'+slug;return '/conta.html';}
async function currentProfilePath(){if(communityStatus?.username)return profilePath(communityStatus.username);let slug=profileSlug;try{slug=slug||await ensureProfileSlug(user?.uid);}catch{}if(slug){profileSlug=slug;return profilePath('',slug);}return user?.uid?'/conta.html?u='+encodeURIComponent(user.uid):'/conta.html';}
